sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.search = '';
    c.categoryFilter = 'all';
    c.certificationFilter = 'all';


    /*
     * =========================================================
     * FILTER SKILL RECORDS
     * =========================================================
     */

    c.getFilteredSkills = function() {

        var skills = c.data.skills || [];
        var results = [];

        var searchText = String(c.search || '')
            .toLowerCase()
            .trim();


        for (var i = 0; i < skills.length; i++) {

            var skill = skills[i];

            var matchesSearch = true;
            var matchesCategory = true;
            var matchesCertification = true;


            /*
             * SEARCH
             */

            if (searchText) {

                var searchable =
                    String(skill.student || '') + ' ' +
                    String(skill.name || '') + ' ' +
                    String(skill.category || '') + ' ' +
                    String(skill.level || '');

                searchable = searchable.toLowerCase();

                matchesSearch =
                    searchable.indexOf(searchText) !== -1;
            }


            /*
             * CATEGORY
             */

            if (c.categoryFilter !== 'all') {

                matchesCategory =
                    String(skill.category || '') ===
                    String(c.categoryFilter);
            }


            /*
             * CERTIFICATION
             */

            if (c.certificationFilter === 'certified') {

                matchesCertification =
                    skill.certification === true;

            } else if (c.certificationFilter === 'not_certified') {

                matchesCertification =
                    skill.certification !== true;
            }


            if (
                matchesSearch &&
                matchesCategory &&
                matchesCertification
            ) {

                results.push(skill);

            }

        }

        return results;
    };


    /*
     * =========================================================
     * REFRESH
     * =========================================================
     */

    c.refresh = function() {

        c.data.action = 'refresh';

        c.server.update();

    };

};

sp_widget.css:
/* ==========================================================================
