   ========================================================================== */

html, body, #sp-page, .sp-page-container, #page_content, .page, main {
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  background-color: #f8fafc !important;
}

/* HIDE SERVICENOW TOP BANNER & NAVBAR FOR ALL TPO PAGE ROOT CONTAINERS */
body #sp-header,
body .sp-header,
body .sp-navbar,
body #sp-nav-bar,
body .sp-nav-bar,
body header#sp-header,
body header.sp-header,
body header.navbar,
body nav.navbar,
body .navbar.sp-navbar,
body .navbar.navbar-default,
body .navbar.navbar-inverse,
#sp-header,
.sp-header,
.sp-navbar,
#responsiveNav,
header#sp-header,
header.sp-header,
header.navbar,
nav.navbar {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  min-height: 0 !important;
  max-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}

/* ZERO MARGIN & PADDING ON SERVICENOW PAGE CONTAINERS */
.page,
#sp-page,
#sp-main,
.sp-page,
.sp-main,
.page-wrapper,
.main-content,
.container,
.container-fluid,
.row {
  width: 100% !important;
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
}

/* FORCE ALL TPO APP ROOT CONTAINERS TO FULLSCREEN FIXED OVERLAY (COVERING TOP NAVBAR 100%) */
.c360-app,
.c360-page,
.campus360-app,
.campus360-company-app,
.campus360-company-page,
.campus360-interviews-app,
.campus360-applications-app,
.campus360-applications-page,
.campus360-tpo-page,
.campus360-opportunity-page,
.campus360-tpo-layout,
.campus360-tpo-app,
