  letter-spacing: 1.4px;
  color: #6941d9;
  margin-bottom: 7px;
}

.page-header h1 {
  margin: 0;
  font-size: 32px;
  font-weight: 800;
  color: #111b38;
}

.page-header p {
  margin: 8px 0 0;
  color: #71809c;
  font-size: 14px;
  max-width: 700px;
  line-height: 1.6;
}

.header-actions {
  display: flex;
  gap: 10px;
  align-items: center;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.primary-btn,
.secondary-btn {
  border-radius: 9px;
  padding: 10px 15px;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
  border: 1px solid transparent;
}

.primary-btn {
  background: #6941d9;
  color: white;
}

.primary-btn:hover {
  background: #5631bd;
  color: white;
  text-decoration: none;
}

.secondary-btn {
  background: white;
  border-color: #dfe4ee;
  color: #46536d;
}

.secondary-btn:hover {
  background: #f7f8fb;
}


/* =========================================================
   FILTER
   ========================================================= */

.filter-card {
  display: flex;
  gap: 12px;
  align-items: center;
  background: white;
  border: 1px solid #e6eaf1;
  border-radius: 14px;
  padding: 14px;
  margin-bottom: 22px;
  box-shadow: 0 3px 12px rgba(31, 43, 75, 0.04);
}

.search-box {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 1;
  min-width: 280px;
  background: #f7f8fb;
  border: 1px solid #e4e8f0;
  border-radius: 9px;
  padding: 0 12px;
}

.search-icon {
  font-size: 18px;
  color: #8b96aa;
}

.search-box input {
  width: 100%;
  border: 0;
  outline: none;
  background: transparent;
  padding: 11px 0;
  font-size: 13px;
}

.filter-card select {
  min-width: 180px;
  padding: 11px 12px;
  border: 1px solid #dfe4ed;
  border-radius: 9px;
  background: white;
  color: #46536d;
  font-size: 13px;
}


/* =========================================================
   SUMMARY
   ========================================================= */

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 22px;
}

.summary-card {
  display: flex;
  align-items: center;
  gap: 14px;
  background: white;
  border: 1px solid #e7ebf2;
  border-radius: 14px;
  padding: 19px;
  box-shadow: 0 3px 12px rgba(31, 43, 75, 0.04);
}

.summary-icon {
  width: 42px;
  height: 42px;
  border-radius: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  font-weight: 700;
}

.summary-card span {
  display: block;
  color: #77839b;
  font-size: 12px;
  margin-bottom: 4px;
}

.summary-card strong {
  font-size: 24px;
  color: #18233f;
}

.summary-card.blue .summary-icon {
  background: #edf4ff;
  color: #3978db;
}

.summary-card.purple .summary-icon {
  background: #f1edff;
  color: #6941d9;
}

.summary-card.green .summary-icon {
  background: #eaf8f0;
  color: #27945d;
}

.summary-card.orange .summary-icon {
  background: #fff3e6;
  color: #e88928;
}


/* =========================================================
   MAIN GRID
   ========================================================= */

.main-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 20px;
  margin-bottom: 20px;
}

.card {
  background: white;
  border: 1px solid #e6eaf1;
  border-radius: 15px;
  padding: 22px;
  box-shadow: 0 3px 12px rgba(31, 43, 75, 0.04);
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 15px;
  margin-bottom: 20px;
}

.card-header h2 {
  margin: 0;
  font-size: 19px;
  font-weight: 800;
  color: #17213b;
}

.card-header p {
  margin: 5px 0 0;
  color: #8a95a8;
  font-size: 12px;
}

.text-link {
  color: #6941d9;
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
}

.text-link:hover {
  text-decoration: underline;
}


/* =========================================================
   CATEGORY
   ========================================================= */

.category-list {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.category-row {
  display: grid;
  grid-template-columns: 160px 1fr 45px;
  align-items: center;
  gap: 12px;
}

.category-info strong {
  display: block;
  font-size: 13px;
  color: #25304a;
}

.category-info span {
  display: block;
  margin-top: 3px;
  color: #8994a8;
  font-size: 11px;
}

.category-bar {
  height: 8px;
  border-radius: 20px;
  background: #eef1f6;
  overflow: hidden;
}

.category-fill {
  height: 100%;
  border-radius: 20px;
  background: #6941d9;
}

.category-percent {
  font-size: 12px;
  color: #56627a;
  text-align: right;
}


/* =========================================================
   TOP SKILLS
   ========================================================= */

.skill-list {
  display: flex;
  flex-direction: column;
}

.skill-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid #edf0f5;
}

.skill-row:last-child {
  border-bottom: 0;
}

.skill-rank {
  width: 27px;
  height: 27px;
  border-radius: 8px;
  background: #f1edff;
  color: #6941d9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 800;
}

.skill-info {
  flex: 1;
}

.skill-info strong {
  display: block;
  font-size: 13px;
  color: #26314b;
}

.skill-info span {
  display: block;
  font-size: 11px;
  color: #8a95a8;
  margin-top: 3px;
}

.skill-count {
  font-weight: 800;
  font-size: 14px;
  color: #46536d;
}


/* =========================================================
   TABLE
   ========================================================= */

.records-card {
  margin-bottom: 20px;
}

.table-wrapper {
  overflow-x: auto;
}

.skills-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 900px;
}

.skills-table th {
  text-align: left;
  padding: 12px 10px;
  background: #f7f8fb;
  color: #758198;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
  text-transform: uppercase;
}

.skills-table td {
  padding: 14px 10px;
  border-bottom: 1px solid #edf0f5;
  color: #46536d;
  font-size: 12px;
}

.skills-table tbody tr:hover {
  background: #fafbfe;
}

.skill-name {
  font-weight: 700;
  color: #25304a;
}

.category-pill,
.level-pill {
  display: inline-block;
  padding: 5px 8px;
  border-radius: 7px;
  background: #f3f5f9;
  color: #59667d;
  font-size: 10px;
  font-weight: 700;
}

.certified {
  color: #27945d;
  font-weight: 700;
  font-size: 11px;
}

.not-certified {
  color: #8a95a8;
  font-size: 11px;
}

.muted {
  color: #9ba4b3;
  font-size: 11px;
}

.empty-table {
  padding: 40px;
  text-align: center;
  color: #8b95a8;
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.empty-state {
  padding: 25px 10px;
  text-align: center;
  color: #8b95a8;
  font-size: 12px;
}


/* =========================================================
   FOOTER
   ========================================================= */

.page-footer {
  display: flex;
  justify-content: space-between;
  color: #8994a8;
  font-size: 11px;
  padding: 5px 2px 20px;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1000px) {

  .summary-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .main-grid {
    grid-template-columns: 1fr;
  }

}

@media (max-width: 700px) {

  .campus360-skill-page {
    padding: 20px;
  }

  .page-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .filter-card {
    flex-wrap: wrap;
  }

  .search-box {
    flex-basis: 100%;
  }

  .summary-grid {
    grid-template-columns: 1fr;
  }

  .category-row {
    grid-template-columns: 120px 1fr 40px;
  }

}
.campus360-tpo-layout,
.tpo-layout,
.tpo-container,
.campus360-skill-intel,
.tpo-dashboard-center {
  position: fixed !important;
