}

sp_widget.script:
(function() {
  try { data.chatbotWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {}); } catch(e) {}

    /*
     * =========================================================
     * CAMPUS360 TPO SKILL INTELLIGENCE
     * Server-side data provider
     * =========================================================
     */

    data.skills = [];

    data.categories = [];

    data.categoryStats = [];

    data.topSkills = [];

    data.stats = {
        totalSkills: 0,
        studentsCovered: 0,
        certified: 0,
        averageScore: 0
    };


    /*
     * =========================================================
     * STUDENT SKILLS
     * =========================================================
     */

    var skillGR = new GlideRecord(
        'x_snc_campus360_student_skills'
    );

    skillGR.orderBy('skill_name');
    skillGR.query();


    var studentMap = {};
    var categoryMap = {};
    var skillMap = {};

    var scoreTotal = 0;
    var scoreCount = 0;


    while (skillGR.next()) {

        var studentName =
            skillGR.student_reference.getDisplayValue();

        var skillName =
            skillGR.getValue('skill_name') || '';

        var category =
            skillGR.getValue('skill_category') || '';

        var skillLevel =
            skillGR.getValue('skill_level') || '';

        var scoreValue =
            skillGR.getValue('assessment_score');

        var certified =
            skillGR.getValue('certification') == 'true';

        var lastAssessed =
            skillGR.getDisplayValue('last_assessed_date') || '';


        /*
         * RECORD
         */

        data.skills.push({

            student: studentName,

            name: skillName,

            category: category,

            level: skillLevel,

            score:
                scoreValue !== null &&
                scoreValue !== undefined &&
                scoreValue !== ''
                    ? parseInt(scoreValue, 10)
                    : '',

            certification: certified,

            lastAssessed: lastAssessed

        });


        /*
         * TOTAL
         */

        data.stats.totalSkills++;


        /*
         * STUDENTS
         */

        if (studentName) {
            studentMap[studentName] = true;
        }


        /*
         * CERTIFICATIONS
         */

        if (certified) {
            data.stats.certified++;
        }


        /*
         * ASSESSMENT SCORE
         */

        if (
            scoreValue !== null &&
            scoreValue !== undefined &&
            scoreValue !== ''
        ) {

            var numericScore =
                parseFloat(scoreValue);

            if (!isNaN(numericScore)) {

                scoreTotal += numericScore;
                scoreCount++;

            }

        }


        /*
         * CATEGORY
         */

        if (category) {

            if (!categoryMap[category]) {

                categoryMap[category] = 0;

            }

            categoryMap[category]++;

        }


        /*
         * SKILL
         */

        if (skillName) {

            if (!skillMap[skillName]) {

                skillMap[skillName] = {
                    name: skillName,
                    category: category,
                    count: 0
                };

            }

            skillMap[skillName].count++;

        }

    }


    /*
     * =========================================================
     * STUDENT COUNT
     * =========================================================
     */

    for (var studentKey in studentMap) {

        if (studentMap.hasOwnProperty(studentKey)) {

            data.stats.studentsCovered++;

        }

    }


    /*
     * =========================================================
     * AVERAGE ASSESSMENT
     * =========================================================
     */

    if (scoreCount > 0) {

        data.stats.averageScore =
            Math.round(scoreTotal / scoreCount);

    }


    /*
     * =========================================================
     * CATEGORIES
     * =========================================================
     */

    for (var categoryKey in categoryMap) {

        if (categoryMap.hasOwnProperty(categoryKey)) {

            data.categories.push(categoryKey);

        }

    }


    data.categories.sort();


    /*
     * =========================================================
     * CATEGORY STATISTICS
     * =========================================================
     */

    var totalCategoryRecords =
        data.stats.totalSkills;


    for (var categoryName in categoryMap) {

        if (categoryMap.hasOwnProperty(categoryName)) {

            var categoryCount =
                categoryMap[categoryName];

            var categoryPercent = 0;

            if (totalCategoryRecords > 0) {

                categoryPercent =
                    Math.round(
                        (categoryCount /
                            totalCategoryRecords) * 100
                    );

            }

            data.categoryStats.push({

                category: categoryName,

                count: categoryCount,

                percent: categoryPercent

            });

        }

    }


    data.categoryStats.sort(function(a, b) {

        return b.count - a.count;

    });


    /*
     * =========================================================
     * TOP SKILLS
     * =========================================================
     */

    for (var skillKey in skillMap) {

        if (skillMap.hasOwnProperty(skillKey)) {

            data.topSkills.push(
                skillMap[skillKey]
            );

        }

    }


    data.topSkills.sort(function(a, b) {

        return b.count - a.count;

    });


    /*
     * Keep the dashboard compact.
     */

    if (data.topSkills.length > 8) {

        data.topSkills =
            data.topSkills.slice(0, 8);

    }


})();

try {
  data.aiWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {});
  data.chatbotWidget = data.aiWidget;
} catch(e) {}
